window.MONSTER_CHUNK_110 = [{"name":"Mimi","cr":1,"xp":400,"alignment":"NG","size":"Tiny","type":"fey","subtypes":["cold"],"init":4,"senses":[{"type":"low-light vision"}],"ac":19,"ac_touch":17,"ac_flat_footed":14,"ac_mods":"+4 Dex, +1 dodge, +2 natural, +2 size","hp":4,"hd":"1d6+1","hdvalue":1,"fort":2,"ref":6,"will":3,"dr":"5/cold iron","immunities":["cold"],"sr":15,"weaknesses":["vulnerability to fire"],"speed":[{"type":"land","speed":20},{"type":"fly","speed":50,"maneuverability":"average"}],"melee":"short sword +6 (1d3-3)","space":"2-1/2 ft.","reach":"0 ft.","special_attacks":[{"type":"group casting"},{"type":"lower temperature"}],"spell_like_abilities_caster_level":8,"spell_like_abilities_concentration":10,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"invisibility"}]},{"frequency":"1/day","spells":[{"spell":"cone of cold"}]},{"frequency":"2/day","spells":[{"spell":"frost fingers","details":"as burning hands, but cold damage"}]}],"strength":4,"dexterity":19,"constitution":14,"intelligence":15,"wisdom":13,"charisma":14,"baseatk":0,"cmb":2,"cmd":10,"feats":[{"feat":"Dodge","type":"bonus"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Bluff","value":6},{"skill":"Craft (any one)","value":6},{"skill":"Escape Artist","value":8},{"skill":"Perception","value":5},{"skill":"Perform (limericks)","value":6},{"skill":"Perform (sing)","value":6},{"skill":"Sense Motive","value":5},{"skill":"Stealth","value":16},{"skill":"Survival","value":2}],"languages":["Common","Elven","Sylvan"],"environments":["cold forests","cold plains"],"organizations":["gang (2-4)","band (6-11)","tribe (20-80)"],"treasure":"no coins; 50% goods; 50% items","description_visual":"This tiny fey resembles a 1-foot tall elf with small bee-like wings, silver hair, milk white skin, and icy blue eyes. It is dressed in colorful garments of blue, silver, or green and carries a tiny short sword in a scabbard slung across its backs, resting between its wings.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Group Casting","kind":"Sp","details":"A group of three or more mimis together can use freezing sphere (DC 18 half), once per day. Caster level 12th. The save DCs are Charisma-based."},{"type":"Lower Temperature","kind":"Su","details":"A mimi can, as a free action, lower the temperature in a 10-foot radius around its body by 20-80 degrees. Creatures in the area that are not immune or resistant to cold may take damage (see Cold Hazards)."}],"description":"Mimis are 1-foot tall mischievous creatures that inhabit cold forests and fields and derive pleasure from playing tricks on creatures that wander into their icy realm. Mimi tricks are always harmless and include such things as throwing snowballs at a creature, creating a patch of ice on the ground and watching a creature slip and fall, or turning invisible and sneaking into a sleeping creature's camp wherein they put snow or ice in the creature's boots, clothes, or backpack.\n\nWhile frolicsome, mimis are generally good-natured and friendly towards those they encounter. They often lend aid to creatures in need, especially those that have helped a mimi in the past. Mimis will not lend aid or assistance to creatures of a malign nature and tend to avoid such creatures if possible. They are on good terms with most other fey creatures, though they find brownies to be a little too \"stiff\" for their liking and buckawns to be a bit too gruff.\n\nDruids and rangers can detect the presence of a mimi or group of mimis with a successful DC Survival check.\n\nMimis are non-aggressive creatures and rarely attack, unless potential adversaries are inherently evil. They prefer to avoid combat if at all possible but if drawn in, they open using their frost fingers. Against more powerful opponents, mimis begin combat by blasting their foes with a cone of cold.\n\nA persistent foe that wishes to continue the battle against a mimi (after being hit with its frost fingers or cone of cold) is subjected to a rapid decrease in the surrounding temperature. A mimi lowers the temperature just enough to possibly damage an adversary (see cold dangers) and maybe force it away; its goal isn't to kill it.\n\nMimis usually turn invisible and flee if they cannot drive their opponents away.","ecology":"","habitat_society":""},{"name":"Nilbog","cr":1,"xp":400,"alignment":"NE","size":"Small","type":"humanoid","subtypes":["goblinoid"],"init":1,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["spatio-temporal reversal (20 ft., Will DC 11)"],"ac":15,"ac_touch":12,"ac_flat_footed":14,"ac_mods":"+3 armor, +1 Dex, +1 size, +0 natural","hp":5,"hd":"1d8+1","hdvalue":1,"fort":3,"ref":1,"will":-1,"defensive_abilities":["damage reversal"],"speed":[{"type":"land","speed":30}],"melee":"morningstar +1 (1d6)","ranged":"javelin +2 (1d4)","space":"5 ft.","reach":"5 ft.","strength":11,"dexterity":13,"constitution":12,"intelligence":10,"wisdom":9,"charisma":6,"baseatk":0,"cmb":-1,"cmd":10,"feats":[{"feat":"Alertness"}],"skills":[{"skill":"Perception","value":5},{"skill":"Ride","value":5},{"skill":"Sense Motive","value":1},{"skill":"Stealth","value":9}],"languages":["Goblin"],"environments":["temperate plains","temperate underground"],"organizations":["gang (4-9)","band (10-100 plus 100% noncombatants plus 1 3rd-level sergeant per 20 adults and 1 leader of 4th-6th level)","warband (10-24 with worg mounts)","tribe (40-400 plus 100% noncombatants plus 1 3rd-level sergeant per 20 adults, 1 or 2 lieutenants of 4th or 5th level, 1 leader of 6th-8th level, 10-24 worgs, and 2-4 dire wolves)"],"treasure":"standard","description_visual":"This creature resembles a small humanoid with a flat face, broad nose, pointed ears, wide mouth, and small, sharp fangs. It walks upright, but its arms hang down almost to its knees.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Damage Reversal","kind":"Ex","details":"When struck by any attack that would normally damage the nilbog, it actually gains hit points equal to the damage the attack would have otherwise dealt. A nilbog gains any extra hit points above its normal total as temporary hit points, though it can never have more than twice its normal hit points. (Excess hit points are simply lost.). The nilbog can only be damaged through the use of curative magic and effects (cure light wounds and healing potions, for instance). Curative magic deals damage equal to the amount it would normally heal."},{"type":"Spatio-Temporal Reversal","kind":"Ex","details":"A nilbog constantly emanates an aura of confusion in a 20-foot-radius. A creature in the area must succeed on a DC 11 Will save or be affected as if by a confusion spell (caster level 4th). The save DC is Constitution-based."}],"description":"The nilbog is a goblin afflicted with a strange space-time reversal disease known as Nilbogism. The disease appears to occur when overly heavy use of magic strains the fabric of the space-time continuum and leads to some very strange localized events. The disease only affects goblins and isn't transmitted by them. Nilbogs resemble goblins in appearance and are indistinguishable from them. The nilbog favors ambushes, dirty tricks, and overwhelming odds to a fair fight. It moves within range of a foe so as to affect the creature with its spatio-temporal reversal ability. Nilbog leaders tend to be rogues or fighter/rogues. Nilbogs worship various goblin gods of evil and can choose two of the following domains: Chaos, Evil, and Trickery. Most nilbog spellcasters, however, are adepts. Nilbog adepts favor spells that fool or confuse enemies.","as_character":[{"description":"Nilbogs are defined by class levels-they don't possess racial Hit Dice. Nilbogs have the following racial traits.","racial_traits":[{"type":"Ability Score Bonuses","value":"-2 Strength, +2 Dexterity, -2 Charisma. Nilbogs are quick but weak and ugly."},{"type":"Small","value":"Nilbogs are Small creatures and gain a +1 size bonus to their AC, a +1 bonus on attack rolls, a -1 penalty to their CMB and CMD, and a +4 size bonus on Stealth checks."},{"type":"Fast","value":"Nilbogs are fast for their size, and have a base speed of 30 ft."},{"type":"Darkvision","value":"Nilbogs can see in the dark up to 60 ft."},{"type":"Skilled","value":"+4 racial bonus on Stealth checks."},{"type":"Special Attacks","value":"Spatio-temporal reversal Special Defenses: Damage reversal"},{"type":"Languages","value":"Goblins begin play speaking Goblin. Goblins with high Intelligence scores can choose any of these bonus languages: Common, Draconic, Dwarven, Gnoll, Gnome, Halfling, Orc."}]}],"ecology":"","habitat_society":"","credit":"The Nilbog originally appeared in the First Edition Fiend Folio (© TSR/ Wizards of the Coast, 1981) and is used by permission.","gear":"studded leather armor, morningstar, 3 javelins"},{"name":"Nupperibo Devil","cr":1,"xp":400,"alignment":"LE","size":"Medium","type":"outsider","subtypes":["devil","evil","extraplanar","lawful"],"init":0,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"blindsight","modifier":"60 ft."}],"ac":12,"ac_touch":10,"ac_flat_footed":12,"ac_mods":"+2 natural","hp":5,"hd":"1d10","hdvalue":1,"fort":0,"ref":2,"will":2,"dr":"5/good or silver","immunities":["fire","mind-affecting effects","poison"],"resists":[{"type":"acid","value":10},{"type":"cold","value":10}],"speed":[{"type":"land","speed":20}],"melee":"spear +1 (1d6) or 2 claws +1 (1d4)","space":"5 ft.","reach":"5 ft.","strength":10,"dexterity":10,"constitution":10,"wisdom":11,"charisma":4,"baseatk":1,"cmb":1,"cmd":11,"languages":["Infernal (cannot speak)"],"environments":["any (Hell)"],"organizations":["horde (20-100)"],"treasure":"none","description_visual":"This vaguely humanoid creature is about as tall as a human and has clawed hands and dark grayish-black flesh. It wields a spear in its clawed hands.","group":"Devil","source":"Tome of Horrors Complete (3pp)","description":"Those evil souls that are taken to Hell and processed to become lemures but fail ultimately become nupperibo: a life-form even more disgusting and sad than the lowly lemure. Nupperibos are gathered by the dukes and arch-devils and used as fodder in their never-ending wars. A typical nupperibo army consists of thousands of these creatures.\n\nNupperibo stands 5 ft. tall and weigh about 100 pounds.\n\nNupperibos unerringly follow the orders of their commander. They are relentless in their pursuit and attack, and continue to assault anything in their path until ordered to stop by their commander. A nupperibo killed in battle is 99% likely to be reformed (by a duke or arch-devil) into another nupperibo; the remaining 1% are \"promoted\" to lemure status, having proved their worth in combat.","ecology":"","habitat_society":"","credit":"The Nupperibo originally appeared in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission.","gear":"spear"},{"name":"Ogren","cr":1,"xp":400,"alignment":"NE","size":"Medium","type":"humanoid","subtypes":["ogren"],"init":0,"senses":[{"type":"darkvision","modifier":"30 ft."}],"ac":16,"ac_touch":10,"ac_flat_footed":16,"ac_mods":"+4 armor, +2 natural","hp":13,"hd":"2d8+4","hdvalue":2,"fort":5,"ref":0,"will":0,"speed":[{"type":"land","speed":30}],"melee":"longspear +5 (1d8+3 x3 crit)","space":"5 ft.","reach":"5 ft.","strength":17,"dexterity":11,"constitution":14,"intelligence":10,"wisdom":11,"charisma":8,"baseatk":1,"cmb":4,"cmd":14,"feats":[{"feat":"Weapon Focus (longspear)"}],"skills":[{"skill":"Perception","value":2},{"skill":"Stealth","value":4}],"languages":["Common","(Giant or Goblin 50% of either)"],"sq":[{"type":"ogre blood"}],"environments":["temperate hills","temperate plains"],"organizations":["solitary","band (5-8)","raiding party (6-11 and one leader of 5th-7th level)","clan (10-24, plus 100% noncombatants, one shaman of 5th-7th level, one leader of 7th-9th level, 2-4 ogres, and 5-8 hobgoblins)"],"treasure":"standard","description_visual":"This humanoid stands over seven ft. tall, its features an amalgam of goblin and ogre. Coarse brown hair covers its sickly yellowish hide, though its hideous face remains entirely hairless, except for the long, knotted tangle of greasy hair spilling from its head. It stares coldly with deep-set eyes the color of pitch.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Ogre Blood","kind":"Ex","details":"Fifty percent of ogren have enough ogre blood in their veins to qualify as ogres. Those that qualify are considered ogres for all special abilities and effects."}],"description":"Take the worst traits of a male ogre and the worst traits of a female hobgoblin and mix them together, the result is an ogren: a barbaric and primitive race of individuals that see combat as a way of life and means of entertainment and survival. Combat skills and battle prowess are taught at a very young age among the ogren clans, and it isn't unheard of for an entire clan to be led by one who, by any other race would be considered a child, for the mighty rule the weak and the strongest and most combative ogren usually rules a clan. Ogrens pride themselves on combat and employ varying tactics and strategies when engaged in such affairs. Ogrens prefer straightforward tactics to ambush and chicanery, though if outmatched, they are not above employing such tactics. Ogrens usually use gang tactics in battle and prefer unmatched odds where they clearly have the upper hand (three- or four-on-one suits them just fine). Ogrens rarely if ever back down from a fight as they are taught that cowardice is equal to weakness. However, they are also taught that it is foolish to fight while your enemy clearly has the advantage and backing away is ok, so long as the odds are made even (or at least turned in the ogren's favor) the next time the two meet. Ogrens appear as 6-to-8-foot tall stocky humanoids with hairy hides of dark brown, yellowish-brown, or gray. Their eyes are generally gray or black, though some do have green or blue eyes (though blue eyes are extremely rare). Hair color ranges from brown or black to dark red or gray. Most ogren have long hair and rarely if ever sport facial hair. The typical ogren lives to 100 years of age. Ogren Society Being a primitive people, the ogren clans survive by hunting game and gathering wild fruits, berries, and herbs. Most hunting bands consist of 3-5 males and a tracker (usually an ogren ranger of 3rd level). Ogrens typically hunt large game such as moose, deer, buffalo, bison, elk, humans, and elves. Many a hunting foray has led a band of ogrens into a human or elven encampment or settlement. During these raids, targets are often taken alive and carried back to the ogren's lair where they are stored in cages for later consumption. Ogren often fatten up captive humans and elves before eating them (fattening them up provides the ogren clan with more meat). In times when food is scarce, some clans resort to cannibalism and hunt their own (though rarely if ever a member of the same clan; usually an ogren from a rival clan). Ogren clans are found just about anywhere save the coldest of climates, though they tend to favor temperate climates. Food is hard to come by in such harsh extremes, so they prefer moderate to warm climates where a food supply is readily available. A typical ogren settlement consists of crude huts constructed of wood with thatched or wooden roofs. The huts are spread in a circle around a central meeting ground where they dance, engage in combat, cook their food, and hold yearly rituals. Each clan typically holds three or more yearly rituals. Some ogren rituals include the Rites of Manhood, The Taking (marriage), and The Passing (death). During the rites of manhood, a young ogren must display his battle prowess against a member of his clan. These fights are never to the death, but the damage dealt is real. Many ogren proudly display the scars of such fights on their bodies. During The Taking, a male ogren selects a bride from another clan as a mate. The shaman from the male's clan oversees the ceremony and blesses such a union, usually through the ritual sacrifice of a captive human or elf (the blood of either is cast on the ground during this ritual). The last ritual, The Passing, is led by the shaman and consists of the shaman invoking the spirits of dead ancestors to watch over recently slain or deceased ogrens.","as_character":[{"description":"","racial_traits":[{"type":"Ability Score Bonuses","value":"Strength +6, Constitution +4, Charisma -2. Ogren leaders tend to be barbarians. Ogren clerics are usually adepts and are known as shamans among their clans. Ogrens worship Tushnak \"The Totem God\" and can choose from two of the following domains: Animal, Earth, and Evil."},{"type":"Speed","value":"Base speed is 30 ft."},{"type":"Darkvision","value":"Ogren have darkvision to a range of 30 ft."},{"type":"Racial Hit Dice","value":"An ogren begins with two levels of humanoid, which provide 2d8 HD, a base attack bonus of +1, and base save bonuses of Fort +3, Ref +0, and Will +0."},{"type":"Racial Skills","value":"An ogren's humanoid levels give it skill points equal to 5 x (2 + Int modifier)."},{"type":"Racial Feats","value":"An ogren's humanoid levels give it one feat."},{"type":"AC bonus","value":"+2 natural AC Ogre Blood 50% of all ogren are consider ogres for purposes of determining special abilities and effects."},{"type":"Skills","value":"+2 racial bonus to Stealth checks."},{"type":"Languages","value":"Common and Goblin or Giant (50% chance for either). Ogrens with high Intelligence can choose from the following languages: Elven, Goblin or Giant (whichever isn't an automatic language), Orc, and Sylvan."}]}],"ecology":"","habitat_society":"","gear":"hide armor, longspear"},{"name":"Ogrillon","cr":1,"xp":400,"alignment":"CE","size":"Medium","type":"humanoid","subtypes":["ogrillon"],"init":0,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":14,"ac_touch":10,"ac_flat_footed":14,"ac_mods":"+4 natural","hp":13,"hd":"2d8+4","hdvalue":2,"fort":5,"ref":0,"will":-1,"speed":[{"type":"land","speed":30}],"melee":"unarmed strike +6 (1d4+4)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"reinforced fists"}],"strength":19,"dexterity":10,"constitution":14,"intelligence":7,"wisdom":8,"charisma":8,"baseatk":1,"cmb":5,"cmd":15,"feats":[{"feat":"Weapon Focus (unarmed strike)"}],"skills":[{"skill":"Climb","value":8},{"skill":"Perception","value":0}],"languages":["Giant"],"sq":[{"type":"orc/ogre blood"}],"environments":["any land","any underground"],"organizations":["solitary","gang (2-5)","tribe (5-30 plus 1 4th-level sergeant per 10 adults and 1 leader of 5th-7th level)","warband (3-8 plus 10-24 orcs)"],"treasure":"standard","description_visual":"This ugly brute appears to be a mix of ogre and perhaps orc. Its skin is covered in closely fitting bony plates and nodes akin to an alligator. Its hair is greasy, ragged, and generally unkempt. It exudes a strong sour odor from its body.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Orc/Ogre Blood","kind":"Ex","details":"For all special abilities and effects, an ogrillon is considered an orc or ogre. For example, ogrillons can use special ogre or orc weapons or magic items with racially specific ogre or orc powers as if they were ogres or orcs."},{"type":"Reinforced Fists","kind":"Ex","details":"Ogrillons are considered to be armed even when unarmed (i.e., they don't provoke attacks of opportunity from armed opponents when attacking them and can themselves still make an attack of opportunity against an opponent that attacks unarmed). Additionally, they always deal lethal damage rather than nonlethal damage when fighting unarmed."}],"description":"Ogrillons are a fierce half-ogre race born of a union between a female orc and a male ogre. They tend to act like ogres, but they are far more violent and aggressive than their larger kin. Ogrillons are usually only slightly taller than orcs, with features that strongly favor their orc parent - so much so that most ogrillons are indiscernible from normal orcs. About 10% of ogrillons resemble their ogre parent, however. Ogrillons love nothing more than combat. They are a race so inborn to be warriors that they seem almost depressed and dejected when they are not involved in melee. They only time an ogrillon laughs is when it is the center of a whirlwind of melee and covered in its opponent's blood. Ogrillons don't care for armor or weapons and in fact carry very little gear at all. They do, however, like gold pieces and usually keep a few in a filthy pouch with other shiny trinkets as lucky charms. Ogrillons disdain the use of armor, relying solely on their natural armor to protect them. They also disdain the use of weapons, preferring to leap headlong into a fray with fists swinging madly. Ogrillon Society Ogrillons have no society to call their own. Since they are born of female orcs, ogrillon children are generally raised in orc clans. Their size, strength, and ferocity are welcomed by the orcs, and ogrillons usually occupy a place of reverence in an orc clan. Ogrillons, of course, think little of the admiration of their orc kin. Battle is the only thought that regularly enters the ogrillon mind.","as_character":[{"description":"Ogrillons have racial Hit Dice and can have class levels. Most ogrillon leaders are barbarians. Ogrillon clerics tend to worship \"the Destroyer,\" and they can choose two of the following domains: Chaos, Evil, Strength, and War. Most ogrillon spellcasters are adepts. Ogrillon characters possess the following racial traits.","racial_traits":[{"type":"Ability Score Bonuses","value":"+8 Strength, +4 Constitution, -4 Intelligence, -2 Wisdom, -2 Charisma. Ogrillons are fierce warriors."},{"type":"Darkvision","value":"Ogrillons can see in the dark up to 60 ft."},{"type":"Racial Hit Dice","value":"An ogrillon begins with two levels of humanoid, which provide 2d8 Hit Dice, a base attack bonus of +1, and base saving throw bonuses of Fort +3, Ref +0, and Will +0."},{"type":"Racial Skills","value":"An ogrillon's humanoid levels give it skill points equal to 2 x (2 + Int modifier)."},{"type":"Racial Feats","value":"An ogrillon's humanoid levels give it one feat."},{"type":"AC","value":"+4 natural armor bonus."},{"type":"Natural Weapons","value":"Ogrillons can fight with 2 unarmed strikes that deal lethal damage (1d4)."},{"type":"Special Attacks","value":"Reinforced fists."},{"type":"Special Qualities","value":"Orc/Ogre blood."},{"type":"Languages","value":"Ogrillons begin play speaking Giant, and can also speak Common if they have an Intelligence of at least 10. Ogrillons with high Intelligence scores can choose from the following languages: Dwarf, Gnoll, Goblin, Orc."}]}],"ecology":"","habitat_society":"","credit":"The Ogrillon originally appeared in the First Edition Fiend Folio (© TSR/Wizards of the Coast, 1981) and is used by permission."},{"name":"Orog","cr":1,"xp":400,"alignment":"LE","size":"Medium","type":"humanoid","subtypes":["orc"],"init":0,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":18,"ac_touch":10,"ac_flat_footed":18,"ac_mods":"+8 armor, +0 natural","hp":23,"hd":"3d8+9 (+3)","hdvalue":3,"fort":5,"ref":1,"will":0,"speed":[{"type":"land","speed":20,"special":"30 ft. without armor"}],"melee":"greataxe +5 (1d12+4)","ranged":"javelin +2 (1d6+3)","space":"5 ft.","reach":"5 ft.","strength":16,"dexterity":10,"constitution":14,"intelligence":10,"wisdom":8,"charisma":8,"baseatk":2,"cmb":5,"cmd":15,"feats":[{"feat":"Skill Focus (Perception)"},{"feat":"Toughness"}],"skills":[{"skill":"Perception","value":5}],"languages":["Common","orc"],"sq":[{"type":"Orc/ogre blood"}],"environments":["temperate hills","temperate mountains"],"organizations":["solitary","pair","gang (2-4)","squad (11-20 plus 2 3rd-level sergeants and 1 leader of 3rd-6th level)","band (20-80 plus 100% noncombatants plus 1 3rd-level sergeant per 10 adults, 5 5th-level lieutenants, and 3 7th-level captains)"],"treasure":"standard","description_visual":"This creature looks like a gray-skinned stocky humanoid with coarse dark hair and dark eyes. Small upward curving tusks jut from its lower jaw.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Orc/Ogre Blood","kind":"Ex","details":"For all special abilities and effects, an orog is considered an orc or ogre. For example, orogs can use special ogre or orc weapons or magic items with racially specific ogre or orc powers as if they were ogres or orcs."}],"description":"Orogs, also called elite orcs or greater orcs, are the much larger kin of normal orcs. They usually reach well over 6 ft. tall but closely resemble normal orcs in all ways except build: orogs are much stronger and stockier. It is believed that orogs are the result of the union of a male orc and female ogre. In contrast to lesser orcs, orogs are highly disciplined and straightforward. Orogs within an orc community quickly rise to leadership positions within their clan, although in orc armies the orogs will segregate themselves into all-orog military units. Orog military units are highly organized, tactically superior, and far more dangerous than those of normal orcs. Such orog units form the vanguard of the army to which they belong. Orogs don't separate themselves into their own clans, despite their tendency to self-segregate while in an orc army. Orogs speak Orc, and those specimens that boast Intelligence scores of at least 10 also speak Common. Orogs prefer weapons that deal massive amounts of damage. They try to avoid subterfuge, favoring direct combat to any other tactics.","as_character":[{"description":"Orogs possess racial Hit Dice and may have class levels. Orogs have the following racial traits.","racial_traits":[{"type":"Ability Score Bonuses","value":"+6 Strength, +4 Constitution, -2 Wisdom, -2 Charisma. Orogs are powerful warriors."},{"type":"Darkvision","value":"Orogs can see in the dark up to 60 ft."},{"type":"Racial Hit Dice","value":"An orog begins with three levels of humanoid, which provide 3d8 Hit Dice, a base attack bonus of +2, and base saving throw bonuses of Fort +3, Ref +1, and Will +1."},{"type":"Racial Skills","value":"An orog's humanoid levels give it skill points equal to 3 x (2 + Int modifier)."},{"type":"Racial Feats","value":"An orog's humanoid levels give it two feats."},{"type":"Special Qualities","value":"Orc/Ogre blood."},{"type":"Languages","value":"Orogs begin play speaking Common and orc. Orogs with high Intelligence scores can choose from the following languages: Dwarf, Gnoll, Goblin, Terran."}]}],"ecology":"","habitat_society":"","credit":"The Orog originally appeared in the Second Edition Monstrous Compendium I (© TSR/Wizards of the Coast, 1989) and is used by permission.","gear":"half-plate, greataxe, 3 javelins"},{"name":"Pestie Mite","cr":1,"xp":400,"alignment":"N","size":"Small","type":"fey","init":3,"senses":[{"type":"darkvision","modifier":"90 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":14,"ac_touch":14,"ac_flat_footed":11,"ac_mods":"+3 Dex, +1 size, +0 natural","hp":7,"hd":"2d6","hdvalue":2,"fort":0,"ref":6,"will":4,"dr":"2/cold iron","weaknesses":["light sensitivity"],"speed":[{"type":"land","speed":40},{"type":"climb","speed":20}],"melee":"dagger +5 (1d3-1/19-20)","ranged":"dart +4 (1d3-1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"hatred"},{"type":"sneak attack","details":"+1d6"}],"spell_like_abilities_caster_level":2,"spell_like_abilities_concentration":2,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"prestidigitation"}]},{"frequency":"1/day","spells":[{"spell":"doom"}]}],"strength":8,"dexterity":17,"constitution":11,"intelligence":6,"wisdom":13,"charisma":10,"baseatk":1,"cmb":-1,"cmd":12,"feats":[{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":7},{"skill":"Climb","value":11},{"skill":"Perception","value":5},{"skill":"Sleight of Hand","value":11},{"skill":"Stealth","value":13}],"languages":["Aklo (cannot speak)"],"environments":["any underground"],"organizations":["solitary","squad (2-8)"],"treasure":"standard","description_visual":"This creature is a rather ugly humanoid about 2 ft. tall. It has long pointed ears and a large round nose. Its skin is grayish-brown.","group":"Mite","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Hatred","kind":"Ex","details":"Pesties receive a +1 bonus on attack rolls against creatures with the dwarf or gnome subtype due to special training against these hated foes."},{"type":"Sneak Attack","kind":"Ex","details":"Pesties have a sneak attack for +1d6 damage that is identical to the rogue ability. This ability stacks with any sneak attack damage that a pestie gains through taking rogue levels."}],"description":"Pesties are the larger, stealthier cousin of the mites. They lack the fangs of their kin but stand taller-though they tend to be leaner-with elongated limbs, long, slender fingers, and large pointed ears. Pesties stand between 2-1/2 and 3 ft. tall and weighs 20 pounds. Pesties don't communicate with others (even those of their own race) except through body language and crude hand signals. It is unknown whether pesties simply cannot or choose not to speak. Unlike mites who like to swarm over enemies in a sudden rush, pesties prefer to utilize their great speed and employ hit-and-run tactics to keep opponents off-balance. Pestie Society Pesties often are found working with or lairing with goblins or (more usually) common mites. They are less likely to band together into large communities than their smaller cousins and have an almost kleptomanic urge to pilfer items of interest or value whenever they see them. This tendency often leads to the pesties being driven out of whatever community they currently live in when their allies' patience reaches an end. However, the trapmaking skills of the mite complement the pesties' adeptness at speed and hit-and-run tactics so that invariably the two groups end up in cooperation again. Pesties that wear out their welcome in a goblin community face a grimmer fate, either succeeding in outrunning their pursuers or ending up in a goblin cook pot.","as_character":[{"description":"Pesties have racial Hit Dice and may possess class levels. Pesties have the following racial traits.","racial_traits":[{"type":"Ability Score Bonuses","value":"-2 Strength, +6 Dexterity, -4 Intelligence, +2 Wisdom, -2 Charisma. Pesties are quicker physically but slower mentally than common mites."},{"type":"Small size","value":"Pesties are Small creatures with a +1 bonus to Armor Class, +1 bonus on attack rolls, +4 bonus on Stealth checks, -1 penalty on CMB/CMD checks, and lifting and carrying limits 3/4 those of Medium characters."},{"type":"Base speed","value":"A pestie's base land speed is 40 ft., and it has a climb speed of 20 ft."},{"type":"Darkvision","value":"Pesties can see in the dark out to 120 ft."},{"type":"Low-light vision","value":"Pesties can see twice as far as humans in conditions of dim light."},{"type":"Racial Hit Dice","value":"A pestie begins play with two levels of fey, which provides 2d6 Hit Dice, a base attack bonus of +1, and base saves of Fort +0, Ref +3, Will +3."},{"type":"Racial Skills","value":"A pestie's fey level gives it skill points equal to 2 x (6 + Int modifier). A pestie receives the following adjustments: +4 racial bonus on Sleight of Hand and Stealth checks."},{"type":"Racial Feats","value":"A pestie's fey levels gives it one feat."},{"type":"Special Attacks","value":"Hatred, spell-like abilities."},{"type":"Special Qualities","value":"Scent, DR 2/cold iron, light sensitivity."},{"type":"Languages","value":"Pesties begin play understanding (but unable to speak) Aklo. Pesties with a high intelligence can choose from the following languages: Goblin, Undercommon."}]}],"ecology":"","habitat_society":"","credit":"The Mite and Pestie originally appeared in the First Edition Fiend Folio (© TSR/Wizards of the Coast, 1981) and are used by permission.","gear":"dagger, 6 darts"},{"name":"Pyre Zombie","cr":1,"xp":400,"alignment":"NE","size":"Medium","type":"undead","init":0,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":12,"ac_touch":10,"ac_flat_footed":12,"ac_mods":"+2 natural","hp":12,"hd":"2d8 (+3)","hdvalue":2,"fort":0,"ref":0,"will":3,"dr":"5/slashing","immunities":["fire","undead traits"],"speed":[{"type":"land","speed":30}],"melee":"slam +4 (1d6+4)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"immolation"}],"strength":17,"dexterity":10,"wisdom":10,"charisma":10,"baseatk":1,"cmb":4,"cmd":14,"feats":[{"feat":"Toughness","type":"bonus"}],"sq":[{"type":"non-staggered"}],"treasure":"none","description_visual":"A rotting corpse walks forward, without the usual hesitation and stuttering steps. After a few steps, it bursts into flames that lick its entire body, although it doesn't seem harmed in the slightest bit.","group":"Zombie","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Immolation","kind":"Ex","details":"The pyre zombie may immolate itself 1/day to cause 2d6 fire damage to all creatures in a 5 ft. radius for 2 rounds. If a pyre zombie is reduced to 0 hot points, it immediately explodes for 1d6 points of fire damage in a 10 ft. radius."},{"type":"Non-Staggered","kind":"Ex","details":"Pyre zombies don't gain the staggered condition as normal zombies."}],"description":"Pyre zombies are the sad, tortured remains of those who were killed just before being burned alive. When the soul departed, their body was taken over by some malignant spirit. The spirit fortified the body from destruction by the fire, and the undead form escape the pyre to wreak its vengeance on the living.\n\nPyre zombies are not harmed by fire, but neither do they seek it out.","ecology":"","habitat_society":"","credit":"Original author James C. Boney  Originally appearing in Dread Saecaroth (© Frog God Games, 2011)"},{"name":"Rakklethorn Toad","cr":1,"xp":400,"alignment":"N","size":"Small","type":"magical beast","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":15,"ac_touch":13,"ac_flat_footed":13,"ac_mods":"+2 Dex, +2 natural, +1 size","hp":13,"hd":"2d10+2","hdvalue":2,"fort":4,"ref":5,"will":0,"speed":[{"type":"land","speed":20}],"melee":"bite +5 (1d4)","ranged":"thorn volley +5 (1d6 plus poison)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"poison"},{"type":"thorns"}],"strength":10,"dexterity":15,"constitution":12,"intelligence":2,"wisdom":10,"charisma":6,"baseatk":2,"cmb":1,"cmd":13,"feats":[{"feat":"Weapon Finesse"}],"skills":[{"skill":"Perception","value":4},{"skill":"Stealth","value":7,"special":"(+ 13 in areas of tall grass or dense undergrowth)."}],"environments":["warm marshes"],"organizations":["pack (2-5)","mating swarm (6-36)"],"treasure":"none","description_visual":"A cat-sized toad about 3-foot long with dozens of small needle-like thorns protruding from its back, hops forth. Its mottled brown and green skin glistens with a dull sheen, while its gray eyes study knowingly.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Poison","kind":"Ex","details":"Thorns-injury; save Fort DC 12; frequency 1/ round for 4 rounds; effect 1d6 Dexterity; cure 1 save. The save DC is Constitution-based. If a rakkelthorn toad is killed or subdued before it has fired all of its thorns in a given day, the poison can be extracted from its remaining thorns. A successful DC 16 Heal or Craft (alchemy) check allows the poison to be changed into a mild anesthetic; one rakkelthorn toad provides enough for one dose. A single dose of this anesthetic, applied to the wound of an injured creature, provides a +2 circumstance bonus to Heal checks (multiple doses don't stack). This bonus lasts for one hour, after which time the anesthesia wears off. Poison cannot be extracted from thorns that have been fired by the rakklethorn."},{"type":"Thorns","kind":"Ex","details":"From its back, the rakklethorn toad can fire a volley of thorns once per round as a standard action. All thorns in the cluster either hit or miss their target and deal 1d6 points of damage plus poison. This attack has a range of 50 ft. with no range increment. The rakklethorn toad can launch a total of 6 such volleys per day."}],"description":"Relatives of poisonous toads, rakklethorns live in small packs in murky swamps. Rakklethorn toad packs are fiercely territorial, and battles between them are frequent. Occasionally, however, the rakklethorn toads enter a mating frenzy. Several packs merge and form a great swarm of noisy frogs that sweeps through the marshes like a wave. After a mating frenzy, females release hundreds of jelly-like eggs into the waters. Of all those eggs, only a very small fraction live long enough to hatch into tadpoles.\n\nA rakklethorn toad attacks by arching its back and firing a volley of thorns at an opponent. It rarely ever closes to melee, preferring to attack at range. If confronted in close quarters, a rakklethorn toad usually flees or if cornered, attacks with its bite.","ecology":"","habitat_society":""},{"name":"Ram","cr":1,"xp":400,"alignment":"N","size":"Medium","type":"animal","init":1,"senses":[{"type":"low-light vision"}],"ac":13,"ac_touch":11,"ac_flat_footed":12,"ac_mods":"+1 Dex, +2 natural","hp":19,"hd":"3d8+6","hdvalue":3,"fort":4,"ref":4,"will":1,"defensive_abilities":["ferocity"],"speed":[{"type":"land","speed":40}],"melee":"gore +3 (1d6+1)","space":"5 ft.","reach":"5 ft.","strength":12,"dexterity":13,"constitution":12,"intelligence":1,"wisdom":11,"charisma":4,"baseatk":2,"cmb":3,"cmd":14,"cmd_special":"+4 vs. trip","feats":[{"feat":"Skill Focus (Perception)"},{"feat":"Toughness"}],"skills":[{"skill":"Perception","value":9}],"environments":["any mountains","any plains","temperate hills"],"organizations":["flock (5-50 plus 1 ram per 10 adults and 2-20 lambs)"],"treasure":"none","description_visual":"Curving horns extend from the sides of this sheep's head, giving it a potent butting attack.","group":"Sheep","source":"Tome of Horrors Complete (3pp)","description":"The statistics here describe the common sheep and ram. Sheep generally flee from danger and avoid combat if possible. If cornered, they attack by biting.\n\nRams are male sheep and are usually encountered leading a flock.\n\nRams attack using their horns. They become aggressive if the flock is threatened.","ecology":"","habitat_society":""},{"name":"Rat-Ghouls","cr":1,"xp":400,"alignment":"N","size":"Small","type":"undead","init":3,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":14,"ac_touch":14,"ac_flat_footed":11,"ac_mods":"+3 Dex, +1 size","hp":4,"hd":"1d8","hdvalue":1,"fort":2,"ref":3,"will":2,"immunities":["undead traits"],"speed":[{"type":"land","speed":40},{"type":"climb","speed":20},{"type":"swim","speed":20}],"melee":"bite +1 (1d4 plus disease)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"disease"},{"type":"paralysis","details":"1d4 rounds, DC 10, elves are immune to this effect"}],"strength":10,"dexterity":17,"intelligence":2,"wisdom":13,"charisma":10,"baseatk":0,"cmb":-3,"cmd":9,"feats":[{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Climb","value":11},{"skill":"Perception","value":4},{"skill":"Stealth","value":11},{"skill":"Swim","value":11}],"environments":["any"],"organizations":["solitary","flood (2-40)"],"treasure":"none","description_visual":"The foulest form of common vermin, rat-ghouls are abnormally large rats that have been infused with necrotic energy, either from proximity to a source of foulness, or feasting upon necrotic flesh.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Disease","kind":"Ex","details":"Filth fever: Bite-injury; save DC 10 Fort; onset 1d3 days; frequency 1/day; effect 1d3 Dex damage and 1d3 Con damage; cure 2 consecutive saves. The save DC is Charisma-based."}],"description":"Resembling giant rats with desiccated, leathery skin, and patches of missing fur and flesh, the rat-ghoul is created when normal or dire rats feast on undead flesh, or being inundated with black magic or necrotic forces. Rat-ghouls may be found in any evil area, and they act much as normal rats in their typical environments.\n\nRat-ghouls retain a spark of their former rat intelligence. They tend to stay in packs, looking to feast on flesh and detritus. If no \"normal\" food is available, the rat-ghouls begin feasting on each other, and then possibly even themselves, so strong is their hunger.\n\nRat-ghouls attack en masse, and attempt to overrun their opponents. Rat-ghouls that successfully take an opponent to the ground swarm and eat the creature as soon as possible. Rat-ghouls retain the ability to paralyze foes as normal ghouls.","ecology":"","habitat_society":"","credit":"Original author James C. Boney  Originally appearing in Dread Saecaroth (© Frog God Games, 2011)"},{"name":"Skulk","cr":1,"xp":400,"alignment":"CE","size":"Medium","type":"humanoid","subtypes":["skulk"],"init":6,"senses":[{"type":"low-light vision"}],"ac":13,"ac_touch":12,"ac_flat_footed":11,"ac_mods":"+2 Dex, +1 natural","hp":11,"hd":"2d8+2","hdvalue":2,"fort":1,"ref":5,"will":1,"save_mods":"-4 penalty vs. fear","defensive_abilities":["chameleon blend","untrackable"],"weaknesses":["cowardice"],"speed":[{"type":"land","speed":30}],"melee":"short sword +1 (1d6)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+1d6"}],"strength":10,"dexterity":14,"constitution":12,"intelligence":10,"wisdom":12,"charisma":6,"baseatk":1,"cmb":1,"cmd":13,"feats":[{"feat":"Improved Initiative"}],"skills":[{"skill":"Perception","value":3},{"skill":"Stealth","value":4,"special":"+19 hiding"}],"languages":["Common"],"environments":["any"],"organizations":["solitary","band (3-8)"],"treasure":"standard","description_visual":"This lithe, gray-skinned humanoid is completely hairless. It has soft, almost childlike facial features.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Chameleon Blend","kind":"Ex","details":"Skulks have the ability to match their skin coloration to the surrounding environment, not unlike a chameleon. This, combined with their natural sneakiness, grants them a +15 racial bonus on Stealth checks when hiding, but only while the majority of their skin is visible to the naked eye. Thus they cannot use this ability while wearing armor or any clothing more than a loincloth. Skulks favor wearing cloaks when lurking on the fringes of civilized society which they can quickly remove so as to make full use of their chameleon blend ability."},{"type":"Cowardice","kind":"Ex","details":"Skulks suffer a -4 penalty to their effective Wisdom against Intimidate skill checks and a -4 penalty vs. fear-based spells and effects due to their innate cowardice."},{"type":"Untrackable","kind":"Ex","details":"Skulks can pass through forest and subterranean settings almost without a trace (double the DC for any tracking attempt)."}],"description":"Skulks are a race of humanoids that dwell on the fringe of other societies. They are a parasitic race-the humanoid equivalent of rats that survive by theft, subterfuge, and at times outright murder. Skulks are consummate cowards, sneaking into humanoid communities under cover of darkness and taking what they desire. Skulks never initiate combat unless there is no other option. They prefer to strike from ambush, a tactic aided by their chameleon-like ability to change their skin tone. Skulks are cowardly opponents, attempting to flee as soon as they are injured or the odds are against them. Skulks are approximately human-sized, but are very lightly built. They have slender, graceful arms and legs. Skulks have no hair, and their eyes are usually pale blue or pink. The grayish skin of a skulk is leathery to the touch, but the skulk has the natural ability to vary its skin tone to match nearly any environment. A typical skulk stands 6 ft. tall and weighs 140 pounds. Skulk Society Skulks dwell in small bands or family groups, living a nomadic existence as they travel from place to place. They move constantly so as not to attract undue attention from local militias. A skulk lair will usually be located in an area that is easily concealed, such as a cave or forest. Occasionally, skulks will sneak into a large city's sewer system and set up a more or less permanent presence there, moving their lair from place to place under the city. Skulks remain hidden during daylight hours, leaving the safety of their lair to conduct forays into the humanoid community under cover of darkness. A favored tactic of a skulk band is to sneak into a residence under cover of darkness and slaughter the entire family. Once that grisly task is complete, the skulks remain to take what they will from the home and leave the following dawn.","as_character":[{"description":"Skulks favor taking levels of rogue, almost to the exclusion of any other class. The rogue's unparalleled competence at stealth, ambush, and escape is a role they are perfectly suited for.","racial_traits":[{"type":"Ability Score Bonuses","value":"+4 Dexterity, +2 Constitution, +2 Wisdom, -4 Charisma. Skulks are nimble and hardy but not very personable."},{"type":"Low-Light Vision","value":"A skulk can see twice as far as a human in dim light."},{"type":"Racial Hit Dice","value":"A skulk begins with two levels of humanoid, which provide 2d8 Hit Dice, a base attack bonus of +1, and base saving throw bonuses of Fort +0, Ref +3, and Will +0."},{"type":"Racial Skills","value":"A skulk's humanoid levels give it skill points equal to 2 x (2 + Int modifier). Its racial class skills are Perception and Stealth. Skulks gain a +15 racial bonus on Stealth checks when hiding due to their chameleon blend ability. They suffer a -4 penalty to their effective Wisdom against Intimidate skill checks due to their innate cowardice."},{"type":"Saves","value":"Skulks have a -4 penalty on all saves against fear spells and effects."},{"type":"Racial Feats","value":"A skulk's humanoid levels give it one feat."},{"type":"AC","value":"+1 natural armor bonus."},{"type":"Chameleon Blend","value":"See entry."},{"type":"Sneak Attack","value":"See entry."},{"type":"Untrackable","value":"See entry."},{"type":"Languages","value":"Skulks begin play speaking Common. Skulks with high Intelligence scores can choose from the following languages: Goblin, Orc, Sylvan, Undercommon."}]}],"ecology":"","habitat_society":"","credit":"The Skulk originally appeared in the First Edition Fiend Folio (© TSR/ Wizards of the Coast, 1981) and is used by permission."},{"name":"Small Acid Quasi-elemental","cr":1,"xp":400,"alignment":"N","size":"Small","type":"outsider","subtypes":["acid","elemental","extraplanar"],"init":4,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["fumes (5 ft., Fort DC 10)"],"ac":16,"ac_touch":11,"ac_flat_footed":16,"ac_mods":"+5 natural, +1 size","hp":5,"hd":"1d10","hdvalue":1,"fort":0,"ref":2,"will":2,"immunities":["acid","elemental traits"],"weaknesses":["vulnerability to water"],"speed":[{"type":"land","speed":20},{"type":"swim","speed":80}],"melee":"slam +2 (1d3 plus 1d3 acid)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"acid"},{"type":"drench"}],"strength":11,"dexterity":10,"constitution":11,"intelligence":4,"wisdom":11,"charisma":11,"baseatk":1,"cmb":0,"cmd":10,"feats":[{"feat":"Improved Initiative"}],"skills":[{"skill":"Knowledge (planes)","value":1},{"skill":"Perception","value":4},{"skill":"Stealth","value":8},{"skill":"Swim","value":8}],"languages":["Aquan"],"environments":["any (Quasi-Plane of Acid)"],"organizations":["solitary"],"treasure":"none","description_visual":"What was once a still puddle of green liquid rises up like a wave, lashing out with acid-dripping tendrils. In the midst of the pool, one can barely make out regions of darker green that form a vaguely human face.","group":"Quasi-elemental","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Acid","kind":"Ex","details":"Acid quasi-elementals are living creatures of acid; any melee hit deals acid damage. Creatures hitting an acid quasi-elemental unarmed or with natural attacks take acid damage as though hit by the quasi-elemental's slam attack."},{"type":"Acid Swimmer","kind":"Ex","details":"Acid quasi-elementals cannot swim in water. The swim speed given in the statistics block is their movement only through acid pools or the acidic nature of their environment on their home plane."},{"type":"Drench","kind":"Ex","details":"The quasi-elemental's touch puts out torches, campfires, exposed lanterns, and other open flames of nonmagical origin if these are of Large size or smaller. The creature can dispel magical fire as dispel magic (caster level equals the quasi-elemental's HD)."},{"type":"Fumes","kind":"Ex","details":"The fumes from an acid quasi-elemental's body act as an inhaled poison. Creatures within 5 ft. of an acid quasi-elemental must make succeed on a Fortitude save or take 1 point of Constitution damage each round. This poison doesn't have a frequency; a creature is safe as soon as it moves more than 5 ft. away from the acid quasielemental."},{"type":"Vulnerability to Water","kind":"Ex","details":"An acid elemental erupts in a violent chemical reaction when touched by water. An acid quasi-elemental takes 1d4 points of fire damage for each gallon of water poured into it. The reaction is so violent that all creatures within 5 ft. of the acid quasi-elemental when the water hits it must succeed on a DC 15 Reflex save or take the same damage. Pouring water onto an acid quasielemental requires a successful ranged touch attack. Water from other sources, such as spells or effects that create water but don't specify an amount in gallons, deal 1d4 points of fire damage per caster level to an acid quasielemental within its area of effect. Damage from water based attacks, like the slam attack of a water elemental, is increased by 50% against an acid quasi-elemental. Note that this reaction doesn't occur when the acid quasielemental touches water, only when water touches the acid quasi-elemental."}],"description":"Nestled among the various elemental there lies a plane composed entirely of acid. It is a place of noxious fumes and roiling, bubbling, pools. Plane jumpers do well to avoid this place as it is considered by many to be one of the deadliest, if not the deadliest, of the elemental based planes. Acid quasi-elementals rarely journey from their native plane, except when summoned. They don't like the Material Plane and when called to the place, are usually angered and always a bit uncomfortable. They have no trouble moving on land, but prefer the sanctity of their native plane to all others. At rest, an acid quasi-elemental is a clear puddle of liquid with a slightly green hue. It can rise up like a wave in a manner similar to a water elemental, or ooze along solid surfaces by sending out tendrils and pulling itself along. Wherever it travels, it leaves behind a shallow trough that emits wisps of smoke. Acid quasi-elementals are almost always encountered in large pools of acid when on the Material Plane and rarely leave these pools when combating foes. A favored tactic is to grab a foe and pull it into the quasielemental's acid pool, subjecting it to massive amounts of acid damage.","ecology":"","habitat_society":""},{"name":"Small Gravity Elemental","cr":1,"xp":400,"alignment":"N","size":"Small","type":"outsider","subtypes":["elemental","extraplanar","gravity"],"init":2,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":15,"ac_touch":15,"ac_flat_footed":13,"ac_mods":"+2 deflection, +2 Dex, +1 size, +0 natural","hp":13,"hd":"2d10+2","hdvalue":2,"fort":1,"ref":5,"will":3,"defensive_abilities":["distortion"],"immunities":["elemental traits","missile weapons","mass-dependent spells"],"speed":[{"type":"fly","speed":100,"maneuverability":"perfect"}],"melee":"slam +5 (1d3+1)","ranged":"missile +5 (damage by type)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"engulf"},{"type":"gravity field","details":"crush 1/day, 5 ft. radius, DC 12, 2d4 bludgeoning"}],"strength":12,"dexterity":15,"constitution":12,"intelligence":4,"wisdom":11,"charisma":11,"baseatk":2,"cmb":2,"cmd":16,"feats":[{"feat":"Throw Anything","type":"bonus"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Fly","value":12},{"skill":"Perception","value":5},{"skill":"Sense Motive","value":5},{"skill":"Stealth","value":11}],"languages":["Gravity Manipulation"],"sq":[{"type":"perfect flier"}],"environments":["any (Plane of Gravity)"],"organizations":["solitary"],"treasure":"none","description_visual":"This creature resembles a miniature black hole hovering several ft. off the ground. It is a circular region of absolute blackness, with a bizarre distortion around its edges as it warps light waves. Four spiraling, rotating arms of debris and light surround the circular region of darkness. Its facial features are small points of light, almost like stars.","group":"Elemental","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Distortion","kind":"Su","details":"The manipulation of light waves around a gravity elemental grants it a +2 deflection bonus to its Armor Class."},{"type":"Engulf","kind":"Ex","details":"A gravity elemental that starts its turn grappling a creature or holding and object up to one size smaller than itself can absorb the creature or object into its swirling form as a full-round action. An engulfed creature or object takes damage equal to the elemental's slam attack each round it remains engulfed and can take no action other than trying to break free by rolling its CMB vs. the gravity elementals CMD. The gravity elemental gains the grappled condition as long as it has a creature engulfed, and it can only engulf one creature at a time. A creature that dies while engulfed by a gravity elemental is smashed into atoms and can only be restored to life by a miracle, wish, or the intervention of a deity. An object that is destroyed while it is engulfed by a gravity elemental is destroyed forever and cannot be restored. There is a 1% non-cumulative chance each round that an engulfed creature or object is sent to a random plane."},{"type":"Gravity Field","kind":"Su","details":"A gravity elemental's manipulation of gravity function like the reverse gravity and telekinesis spells (CL equal to HD). The maximum weight an Elder gravity elemental can lift with its telekinesis isn't restricted to 375 lbs. The effects of the gravity field are centered on the gravity elemental and move with it. Additionally, by increasing the pull of gravity around itself a gravity elemental can make creatures within a certain radius too heavy to move, or crush them to a pulp. Hold: As a full-round action a gravity elemental can cause all corporeal creatures in its area of effect to become too heavy to move. Creatures in the gravity elemental's gravity field must succeed on a Fortitude save or gain the held condition until the gravity elemental releases them or they break free. A flying creature has a -4 penalty applied to the save; failure means it is unable to remain airborne and must land. The check DC is Strength-based. The gravity elemental can maintain this ability each round as a fullround action. The area of effect and save DC depend on the size of the elemental. If the gravity elemental maintains this ability, on successive rounds a held creature can break free by succeeding on a Strength check with a DC equal to the initial Fortitude save. Any land-bound creature two size categories smaller less than the elemental has its speed automatically reduced by half, even if the Strength check is successful. This ability only works on creatures with weight and mass; incorporeal and gaseous creatures are immune to this power. Crush: Once per day per 2HD, as a standard action, a gravity elemental can increase the gravity around itself to crushing proportions. Anything within the gravity elemental's gravity field takes bludgeoning damage. A successful Fortitude save reduces the damage by half. The area of effect and save DC depend on the elemental's size. The save DC is Strength-based."},{"type":"Immunity to Missile Weapons","kind":"Ex","details":"A gravity elemental is immune to any attack from thrown or hurled weapons, arrows, bolts, stones, and similar weapons with a size equal to or less than its own. Any such ranged attack against a gravity elemental automatically fails and the weapon is pulled into the elemental's body. Captured missiles orbit the gravity elemental's form as long as it desires, and it can release one such missile each round as an improvised thrown weapon. The weapon deals its normal damage plus the gravity elemental's Strength modifier, and has a range increment of 20 ft. A gravity elemental has the Throw Anything feat as a bonus feat."},{"type":"Immunity to Spells","kind":"Ex","details":"A gravity elemental is immune to all spells, spell-like abilities, and effects that depend on weight or mass."},{"type":"Perfect Flier","kind":"Ex","details":"A gravity elemental has perfect control over the forces of gravity, and never needs to make a Fly check when attempting a complex maneuver. It must still make Fly checks to resist external influences on its flight, such as strong winds."}],"description":"A gravity elemental embodies the very force that controls and holds together the fabric of the universe. The actual elemental is a tiny, superdense ball of matter deep within a zone of darkness and spiraling arms of debris that comprise the body of the elemental. A gravity elemental has mass and size, but no effective weight. Gravity elementals originate on a weird, recently discovered plane that scholars affectionately call the Plane of Gravity. The elemental's home plane is a flat, rocky place with little life, no known water sources, and no plant life or foliage. The plane is always shrouded in darkness. Dense pockets of intense gravity and areas of little or no gravity dot the barren landscape. Gravity elementals seem to be able to converse with others of their kind by manipulating gravity itself. Gravity elementals attack primarily by flailing at their opponents with multiple arms, each one a mixture of fluctuating fields of micro-gravity and debris that has been sucked into its gravity well. These creatures can also attack by adjusting the local gravity fields around themselves.","ecology":"","habitat_society":""},{"name":"Small Smoke Elemental","cr":1,"xp":400,"alignment":"N","size":"Small","type":"outsider","subtypes":["air","elemental","extraplanar","fire"],"init":2,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":16,"ac_touch":13,"ac_flat_footed":14,"ac_mods":"+2 Dex, +3 natural, +1 size","hp":11,"hd":"2d10","hdvalue":2,"fort":3,"ref":5,"will":0,"defensive_abilities":["air mastery","amorphous"],"immunities":["elemental traits","fire"],"weaknesses":["vulnerability to cold","vulnerability to wind"],"speed":[{"type":"fly","speed":80,"maneuverability":"perfect"}],"melee":"slam +3 (1d4 plus burn)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"burn","details":"1d3, DC 9"},{"type":"engulf","details":"DC 11"}],"strength":11,"dexterity":15,"constitution":11,"intelligence":4,"wisdom":11,"charisma":11,"baseatk":2,"cmb":1,"cmd":13,"cmd_special":"can't be tripped","feats":[{"feat":"Flyby Attack"}],"skills":[{"skill":"Fly","value":17},{"skill":"Perception","value":5},{"skill":"Stealth","value":11,"special":"+19 in smoke or fog"}],"languages":["Auran"],"sq":[{"type":"gaseous"}],"environments":["any (Plane of Air)","any (Plane of Fire)","any (Plane of Smoke)"],"organizations":["solitary","pair","gang (3-8)"],"treasure":"none","description_visual":"A black cloud of acrid smoke drifts ahead.","group":"Elemental","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Air Mastery","kind":"Ex","details":"Airborne creatures take a -1 penalty on attack and damage rolls against a smoke elemental."},{"type":"Burn","kind":"Ex","details":"A smoke elemental's burn DC includes a -2 racial penalty, as their fires don't burn as hot as a true fire elemental's flames."},{"type":"Engulf","kind":"Ex","details":"A smoke elemental can engulf creatures of its size or smaller into its smoky form as part of a standard action. It cannot make any other attack in which it engulfs. The smoke elemental merely has to move over its opponents, affecting as many as it can cover. Targeted creatures can make attacks of opportunity against the creature, but if they do so, they are not entitled to a saving throw against the engulf attack. Those who don't attempt attacks of opportunity can attempt a Reflex save to avoid being engulfed-on a success, they move back or aside (target's choice). The smoke obscures all sight, including darkvision, beyond 5 ft. and grants concealment to creatures inside the cloud from attacks by opponents that are not adjacent to them. Engulfed opponents don't gain the pinned condition and may move normally. Each round a creature begins its turn engulfed, it suffers from burning eyes (-2 on attack rolls and Perception checks) and takes 3d6 points of fire damage from smoke inhalation. The penalties and damage continue for a number of rounds equal to the smoke elemental's Hit Dice even after escaping the engulf. A creature can make a Fortitude save (DC is listed with each elemental) to end the penalties and damage. The save DCs are Constitution-based."},{"type":"Gaseous","kind":"Ex","details":"A smoke elemental can pass through small holes or narrow openings without reducing its speed."},{"type":"Vulnerability to Wind","kind":"Ex","details":"A smoke elemental is treated as two sizes smaller for purposes of determining the effects high wind has upon it."}],"description":"Smoke elementals are creatures of elemental smoke: part fire, part air. Where the Elemental Plane of Air meets the Elemental Plane of Fire lies a para-elemental plane, that of Elemental Smoke. It is from that black clouded region that these creatures hail.\n\nSmoke elementals spend most of their time on their home plane, only occasionally venturing into the Elemental Planes of Air or Fire. Rarely do they ever enter the Material Plane unless called by a spellcaster.\n\nA smoke elemental appears as a cloud of black smoke or thick fog. No discernible features can be seen in its form, though it can reshape itself at will to form two large eyes and a mouth of empty darkness (which serve no purpose other than to perhaps startle onlookers).","ecology":"","habitat_society":""},{"name":"Sprite","cr":1,"xp":400,"alignment":"NG","size":"Small","type":"fey","init":4,"senses":[{"type":"low-light vision"}],"ac":16,"ac_touch":16,"ac_flat_footed":11,"ac_mods":"+4 Dex, +1 dodge, +1 size, +0 natural","hp":4,"hd":"1d6+1","hdvalue":1,"fort":1,"ref":6,"will":5,"dr":"5/cold iron","speed":[{"type":"land","speed":30},{"type":"fly","speed":50,"maneuverability":"good"}],"melee":"short sword +5 (1d4-1/19-20)","ranged":"shortbow +5 (1d4/x3 plus poison)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":8,"spell_like_abilities_concentration":9,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"detect evil","details":"range 150 ft."},{"spell":"detect good","details":"range 150 ft."},{"spell":"invisibility","details":"self only"}]}],"strength":8,"dexterity":18,"constitution":12,"intelligence":12,"wisdom":16,"charisma":16,"baseatk":0,"cmb":-2,"cmd":13,"feats":[{"feat":"Dodge"},{"feat":"Weapon Finesse","type":"bonus"}],"skills":[{"skill":"Bluff","value":7},{"skill":"Craft (any one)","value":5},{"skill":"Fly","value":13},{"skill":"Knowledge (local or nature)","value":5},{"skill":"Perception","value":7},{"skill":"Perform (any one)","value":7},{"skill":"Sense Motive","value":7},{"skill":"Stealth","value":9}],"languages":["Common","Elven","Sylvan","speak with animals"],"sq":[{"type":"immortal"},{"type":"poison use"}],"environments":["temperate forests"],"organizations":["gang (2-4)","band (6-11)","tribe (10-100)"],"treasure":"no coins, 50% goods, 50% items","description_visual":"This tiny winged elf-like creature has delicate features, transparent wings, and fair skin. It wears brightly colored clothes and its eyes sparkle with light.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Immortal","kind":"Ex","details":"Sprites are one of the few races that are truly immortal, never aging. They cannot die from natural causes. They still need to eat, sleep, and breathe, and can be killed normally."},{"type":"Poison Use","kind":"Ex","details":"A sprite is never at risk of poisoning itself when handling poison. They use sprite poison on their arrows."},{"type":"Speak with Animals","kind":"Su","details":"Sprites can communicate with animals as the spell of the same name. This innate supernatural ability is always active and cannot be negated or dispelled."}],"description":"A reclusive folk, sprites live in meadows and woodland glens, where they have appointed themselves the monitors of their lands. They stand about 2 ft. tall and fly by means of their tiny diaphanous wings. Sprites have very delicate features with tiny, upturned noses and large pointed ears. Their eyes sparkle like moonlight on a forest lake, and their tiny, high-pitched voices sound almost like music.\n\nSprites are shy and reclusive, avoiding contact with other races; only druids have regular contact with sprites, and indeed many druids get their training from sprites. However, sprites detest evil and attack it on sight with their weapons, preferring to strike from ambush while invisible. If possible, they render their victim unconscious using their envenomed arrows, then spirit the creature away to some remote location where it is placed without weapons or gear and left to fend for itself. Creatures that have demonstrated especially evil characteristics may be slain outright, however.\n\nUnlike their pixie cousins, sprites are not especially mischievous by nature, and prefer to be left alone.\n\nSprite Poison: Type injury; save DC 15; frequency 1/ min. for 2 min.; effect unconscious 1 minute/ 2d4 hours; cure 1 save.\n\nSea Sprite Sea sprites are the aquatic version of normal sprites. As their name implies, they are joyful fey who dwell in the sea. Their hair resembles strands of seaweed and they have large, fish-like eyes. The skin of a sea sprite is pale blue. Lacking wings, sea sprites cannot fly, but thanks to fine webbing in their fingers and toes they are adept swimmers. Sea sprites can breathe both air and water without difficulty. Like normal sprites, sea sprites make use of special ammunition that put their opponents to sleep.\n\nSea sprites have the same statistics as their land-dwelling brethren, with the following exceptions: They have the aquatic and amphibious subtypes; they don't have a fly speed but have a swim speed of 30 ft., and their Swim score is +12 (Swim score is based on their Dexterity, not their Strength). They employ crossbows rather than shortbows, and prefer spears over short swords.","ecology":"","habitat_society":"","credit":"The Sprite originally appeared in the First Edition Monster Manual (© TSR/Wizards of the Coast, 1977) and is used by permission.","gear":"short sword, shortbow, 20 poisoned arrows (sprite poison)"},{"name":"Stormwarden","cr":1,"xp":400,"alignment":"NE","size":"Medium","type":"humanoid","subtypes":["stormwarden"],"init":4,"senses":[{"type":"low-light vision"}],"ac":13,"ac_touch":11,"ac_flat_footed":13,"ac_mods":"+2 armor, +1 natural","hp":16,"hd":"3d8+3","hdvalue":3,"fort":2,"ref":3,"will":2,"speed":[{"type":"land","speed":30}],"melee":"longsword +3 (1d8+1)","ranged":"longbow +2 (1d8)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"conjure storm"}],"strength":12,"dexterity":10,"constitution":12,"intelligence":15,"wisdom":13,"charisma":10,"baseatk":2,"cmb":3,"cmd":13,"feats":[{"feat":"Improved Initiative"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Acrobatics","value":3},{"skill":"Knowledge (any one)","value":5},{"skill":"Perception","value":7},{"skill":"Survival","value":7}],"languages":["Common","Draconic","Giant"],"environments":["temperate mountains"],"organizations":["solitary","pair","gang (3-6)"],"treasure":"standard","description_visual":"This humanoid has dark hair and eyes. Its skin is sapphire colored, and its hair is long. A long beard dominates its countenance. It is dressed in leather armor and furs.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Conjure Storm","kind":"Su","details":"Once per day as a standard action, a stormwarden can create an effect similar to a control weather spell (caster level 10th), except that it affects an area in a 1,000-foot-radius circle, and the weather effects are immediate rather than gradual. The effects last for 1 minute before the weather in the area returns to normal."}],"description":"Stormwardens dwell high in the mountains and hills away from civilization. They are hunters by nature and spend their time hunting and trapping game, though they never do so to an abundance, only enough to sustain themselves. They are isolationists and solitary, rarely found in groups of more than 6 individuals. Their hair color and eye color range across the spectrum just as a normal human, though most tend to have dark hair and eyes. Stormwardens prefer to avoid combat, but if provoked, they open combat using their longswords, attempting to slay their opponents before escaping to their lair. If melee goes against a stormwarden, it alters the weather and attempts to escape.","as_character":[{"description":"Stormwardens favor nature-oriented classes, such as druid and ranger. They don't worship a single deity above all others, though they do tend to favor deities of storms and destruction. Though relatively few in number, stormwarden witches have a reputation of being some of the blackest and most vile practitioners of that art.","racial_traits":[{"type":"Ability Score Bonuses","value":"+2 Strength, +2 Constitution, +4 Intelligence, +2 Wisdom."},{"type":"Low-Light Vision","value":"Stormwardens can see twice as far as humans in dim light."},{"type":"Racial Hit Dice","value":"A stormwarden begins with three levels of humanoid, which provide 3d8 Hit Dice, a base attack bonus of +2, and base saving throw bonuses of Fort +1, Ref +3, and Will +1."},{"type":"Racial Skills","value":"A stormwarden's humanoid levels give it skill points equal to 2 x (2 + Int modifier)."},{"type":"Racial Feats","value":"A stormwarden's humanoid levels give it two feats, typically Improved Initiative and Skill Focus (Perception)."},{"type":"AC","value":"+1 natural armor bonus."},{"type":"Special Attacks","value":"Conjure storm."},{"type":"Languages","value":"Stormwardens begin play speaking Common, and can select bonus languages from the following: Aklo, Auran, Draconic, Elven, Giant, and Sylvan."}]}],"ecology":"","habitat_society":"","gear":"leather armor, longsword, longbow, 20 arrows"},{"name":"Vapor Dire Rat","cr":1,"xp":400,"alignment":"N","size":"Small","type":"magical beast","subtypes":["augmented animal","vapor"],"init":3,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":15,"ac_touch":14,"ac_flat_footed":12,"ac_mods":"+3 Dex, +1 natural, +1 size","hp":6,"hd":"1d10+1","hdvalue":1,"hp_mods":["fast healing 2"],"fort":3,"ref":5,"will":1,"resists":[{"type":"fire","value":5}],"weaknesses":["cold susceptibility"],"speed":[{"type":"land","speed":40},{"type":"climb","speed":20},{"type":"swim","speed":20}],"melee":"bite +5 (1d4 plus disease)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"death throes","details":"DC 11"},{"type":"disease"}],"strength":10,"dexterity":17,"constitution":12,"intelligence":6,"wisdom":13,"charisma":10,"baseatk":1,"cmb":0,"cmd":13,"cmd_special":"+4 vs. trip","feats":[{"feat":"Weapon Finesse"}],"skills":[{"skill":"Climb","value":11},{"skill":"Stealth","value":11,"special":"+19 in areas of smoke, fog, mist or vapor"},{"skill":"Swim","value":11}],"languages":["Common (can't speak)"],"sq":[{"type":"vaporous form"}],"environments":["any"],"organizations":["solitary","pack (11-20)"],"treasure":"none","description_visual":"This creature looks like a larger, more aggressive version of a normal rat. Its fur is coarse and brown, its eyes green, and its tail is hairless.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Disease","kind":"Ex","details":"Filth fever: Bite-injury; save Fort DC 11; onset 1d3 days; frequency 1/day; effect 1d3 Dex damage and 1d3 Con damage; cure 2 consecutive saves. The save DC is Constitution-based."}],"description":"Vapor dire rats resemble normal dire rats in all respects. Though more intelligent than dire rats, they seem to possess a lot of the same traits and conduct themselves in much the same way as normal dire rats.\n\nThey seldom keep company with their normal counterparts and often times quarrel and fight with dire rats. Vapor dire rats are found just about anywhere save the coldest of climates. Common encounters occur underground or in ruined castles, keeps, temples, and so forth. Regardless of where these creatures construct their nest, a source of water is always found nearby.\n\nVapor dire rats attack with their bite. A pack uses ambush tactics against potential prey, and when attacking, they often attempt to flank their foe, sending several rats against the creature's flank while the rest hit from the front or sides. Injured vapor dire rats drop back where they can use their fast healing ability (if they are near a source of water, fog, steam, or mist) while the holes in their ranks are filled by other vapor dire rats. Vapor dire rats usually assume vapor form and attempt to escape if they lose more than half their numbers.","ecology":"","habitat_society":""},{"name":"Vegepygmy Worker","cr":1,"xp":400,"alignment":"N","size":"Small","type":"plant","subtypes":["fungus"],"init":2,"senses":[{"type":"low-light vision"}],"ac":16,"ac_touch":13,"ac_flat_footed":14,"ac_mods":"+2 Dex, +3 natural, +1 size","hp":16,"hd":"3d8+3","hdvalue":3,"fort":3,"ref":3,"will":1,"dr":"5/bludgeoning or slashing","immunities":["electricity","plant traits"],"speed":[{"type":"land","speed":30}],"melee":"2 claws +3 (1d3) or spear +3 (1d6/x3)","ranged":"spear +5 (1d6/x3)","space":"5 ft.","reach":"5 ft.","strength":11,"dexterity":14,"constitution":11,"intelligence":8,"wisdom":11,"charisma":10,"baseatk":2,"cmb":1,"cmd":13,"feats":[{"feat":"Skill Focus (Perception)"},{"feat":"Toughness"}],"skills":[{"skill":"Perception","value":9},{"skill":"Stealth","value":10,"special":"+18 in forested or swampy areas"}],"environments":["any underground"],"organizations":["(Commoner and Worker) gang (2-5)","work force (4-7)"],"treasure":"standard","description_visual":"This creature resembles a humanoid with green vegetable-like skin and razor-sharp claws. Its head sports two large yellow eyes, a wide mouth, inset nose, and a topknot of dark brown leaves. Leafy tendrils protrude from its shoulders, midsection, arms, and legs.","group":"Vegepygmy","source":"Tome of Horrors Complete (3pp)","description":"When a living creature is slain by russet mold (see that entry), it rises as a vegepygmy commoner. Vegepygmies are low-intelligence plants that make their home deep in the forests or underground away from most settled areas. They are hunters and scavengers, and carnivorous, preying on living creatures weaker than themselves. A vegepygmy ranges from two ft. to four and a half ft. tall. Though they don't seem to have ears, it is well known that vegepygmies can hear. Vegepygmies don't speak, but communicate with others of their kind by thumping their chest or rapping their spears on rocks, earth, or some other solid surface. It isn't known if or how they communicate with other creatures. Vegepygmies attack with claws or weapons, usually either a longspear or club. They prefer to ambush opponents, using their coloration to blend with their natural surroundings.","ecology":"","habitat_society":"","credit":"The Vegepygmy originally appeared in the First Edition module S3 Expedition to the Barrier Peaks (© TSR/Wizards of the Coast, 1980) and later in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission.","gear":"spear"},{"name":"Witherstench","cr":1,"xp":400,"alignment":"N","size":"Small","type":"magical beast","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"auras":["stench (DC 12, while within 30 ft. plus 1 round)"],"ac":14,"ac_touch":13,"ac_flat_footed":12,"ac_mods":"+2 Dex, +1 natural, +1 size","hp":13,"hd":"2d10+2","hdvalue":2,"fort":4,"ref":5,"will":0,"speed":[{"type":"land","speed":20}],"melee":"2 claws +5 (1d4-1)","space":"5 ft.","reach":"5 ft.","strength":8,"dexterity":14,"constitution":12,"intelligence":2,"wisdom":10,"charisma":4,"baseatk":2,"cmb":0,"cmd":12,"cmd_special":"+4 vs. trip","feats":[{"feat":"Weapon Finesse"}],"skills":[{"skill":"Perception","value":5}],"environments":["temperate forests"],"organizations":["pack (3-12)"],"treasure":"standard","description_visual":"This creature resembles a putrid yellow skunk with very little fur and whose body is splotched with tiny purple spots. Patches of darker fur are sprinkled about its body.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Stench","kind":"Ex","details":"A witherstench constantly emits a putrid stench that nearly every form of animal life finds offensive. All living creatures (except witherstenches) within 30 ft. of a witherstench must succeed on a DC 12 Fortitude save or be nauseated (unable to attack, cast spells, concentrate on spells, or do anything else requiring attention; can only take a single move action per turn) for as long as they remain within 30 ft. of the creature. Moving out of the affected area leaves the character sickened (-2 penalty on all attack rolls, weapon damage rolls, saving throws, skill checks, and ability checks) for 1 round after which time he recovers immediately. The save DC is Constitution-based. Creatures that successfully save cannot be affected by the same witherstench's stench for 24 hours. A delay poison or neutralize poison spell removes the effect from the sickened creature. Creatures with immunity to poison are unaffected, and creatures resistant to poison receive their normal bonus on their saving throws."}],"description":"A witherstench (also called skunk beast) is a mutated relative of the common skunk. It is about 4 ft. long and weighs around 50 pounds. Its diet consists of carrion, and the creature is always found in areas where such \"food\" is plentiful.\n\nWitherstenches shuns combat, but attacks if cornered, raking at their opponents with their filthy claws.","ecology":"","habitat_society":"","credit":"The Witherstench originally appeared in the First Edition Fiend Folio (© TSR/Wizards of the Coast, 1981) and is used by permission."}];
